UPDATE `quest_template_locale` SET `Details` = 'Ну, вот, готово, Выручалкин - это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.$b$bУдачи тебе. Да рассеют твои победы мрак!', `VerifiedBuild` = 0 WHERE `locale` = 'ruRU' AND `ID` = 5511;
